Theorem raw_malloc_L X P n : 0 <= n ->
  mspecL LBUDGET (fun s mo => QI X P s mo /\ ROOMX X P n /\ n <= NREQ /\ PHI P + R63X X + bigb n <= LBUDGET) (raw_malloc n)
         (fun r s mo => match r with
                        | Some p => QI ((p, n) :: X) P s mo /\ n < 2 ^ 63
                        | None => QI X P s mo
                        end).
